// Достаём id записи NocoDB.
// Вариант A: инлайн-кнопка "✅ Одобрить" с callback_data = "approve:<recordId>"
// Вариант B: текстовая команда "/approve <recordId>"
const cq = $json.callback_query;
const msg = $json.message;

let recordId = null;
let mode = null;

if (cq && typeof cq.data === 'string' && cq.data.startsWith('approve:')) {
  recordId = cq.data.split(':')[1];
  mode = 'callback';
} else if (msg && typeof msg.text === 'string') {
  const m = msg.text.trim().match(/^\/approve[_\s]+(\d+)$/i);
  if (m) {
    recordId = m[1];
    mode = 'command';
  }
}

if (!recordId) {
  return [{ json: { skip: true } }];
}

return [{
  json: {
    skip: false,
    mode,
    recordId: Number(recordId),
    replyChatId: (cq ? cq.from.id : msg.chat.id),
    callbackQueryId: cq ? cq.id : null
  }
}];
